INSERT INTO "Document" ("id", "userId", "testAccountId", "version", "name", "type", "url", "request", "standard", "header", "date") VALUES (1682433103665, 82002, 0, 3, '创建推送 API', 'JSON', '/v4/push', '{\n    "from": "push",\n    "to": "all",\n    "body": {\n        "platform": "all",\n        "notification": {\n            "android": {\n                "alert": "Hi, Push!",\n                "title": "Send to Android",\n                "builder_id": 1,\n                "extras": {\n                    "newsid": 321\n                }\n            },\n            "ios": {\n                "alert": "Hi, MTPush!",\n                "sound": "default",\n                "badge": "+1",\n                "extras": {\n                    "newsid": 321\n                }\n            }\n        },\n        "message": {\n            "msg_content": "Hi,MTPush",\n            "content_type": "text",\n            "title": "msg",\n            "extras": {\n                "key": "value"\n            }\n        },\n        "options": {\n            "time_to_live": 60,\n            "apns_production": false\n        }\n    },\n    "request_id": "12345678",\n    "custom_args": "business info"\n}', '{\n    "notnull": true,\n    "type": "object",\n    "valueLevel": 0,\n    "values": [\n        {\n            "from": {\n                "notnull": false,\n                "type": "string",\n                "valueLevel": 3,\n                "values": [],\n                "lengthLevel": 1,\n                "lengths": [\n                    4\n                ],\n                "repeat": 16,\n                "comment": " 当前业务发送方"\n            },\n            "to": {\n                "notnull": true,\n                "type": "string",\n                "valueLevel": 3,\n                "values": [],\n                "lengthLevel": 1,\n                "lengths": [\n                    3\n                ],\n                "repeat": 16,\n                "comment": "String 或 JSON Object, 发送目标"\n            },\n            "body": {\n                "notnull": true,\n                "type": "object",\n                "valueLevel": 0,\n                "values": [\n                    {\n                        "platform": {\n                            "notnull": true,\n                            "type": "string",\n                            "valueLevel": 3,\n                            "values": [],\n                            "lengthLevel": 1,\n                            "lengths": [\n                                3\n                            ],\n                            "repeat": 16,\n                            "comment": "String 或 JSON Array, 推送平台"\n                        },\n                        "notification": {\n                            "notnull": true,\n                            "type": "object",\n                            "valueLevel": 0,\n                            "values": [\n                                {\n                                    "android": {\n                                        "notnull": false,\n                                        "type": "object",\n                                        "valueLevel": 0,\n                                        "values": [\n                                            {\n                                                "alert": {\n                                                    "notnull": true,\n                                                    "type": "string",\n                                                    "valueLevel": 3,\n                                                    "values": [],\n                                                    "lengthLevel": 1,\n                                                    "lengths": [\n                                                        9\n                                                    ],\n                                                    "repeat": 16,\n                                                    "comment": "通知内容：这里指定后会覆盖上级统一指定的 alert 信息。内容可以为空字符串，表示不展示到通知栏。各推送通道对此字段的限制详见 推送限制。"\n                                                },\n                                                "title": {\n                                                    "notnull": false,\n                                                    "type": "string",\n                                                    "valueLevel": 3,\n                                                    "values": [],\n                                                    "lengthLevel": 1,\n                                                    "lengths": [\n                                                        15\n                                                    ],\n                                                    "repeat": 16,\n                                                    "comment": " 通知标题：如果指定了，则通知里原来展示 App 名称的地方，将展示 title。各推送通道对此字段的限制详见 推送限制 。"\n                                                },\n                                                "builder_id": {\n                                                    "notnull": false,\n                                                    "type": "integer",\n                                                    "valueLevel": 0,\n                                                    "values": [\n                                                        1\n                                                    ],\n                                                    "lengthLevel": 1,\n                                                    "lengths": [\n                                                        1\n                                                    ],\n                                                    "repeat": 32,\n                                                    "trend": {\n                                                        "top": 16\n                                                    },\n                                                    "comment": " 通知栏样式ID：Android SDK 可 设置通知栏样式，这里根据样式 ID 来指定该使用哪套样式。"\n                                                },\n                                                "extras": {\n                                                    "notnull": false,\n                                                    "type": "object",\n                                                    "valueLevel": 0,\n                                                    "values": [\n                                                        {\n                                                            "newsid": {\n                                                                "notnull": true,\n                                                                "type": "integer",\n                                                                "valueLevel": 0,\n                                                                "values": [\n                                                                    321\n                                                                ],\n                                                                "lengthLevel": 1,\n                                                                "lengths": [\n                                                                    3\n                                                                ],\n                                                                "repeat": 32,\n                                                                "trend": {\n                                                                    "top": 16\n                                                                }\n                                                            }\n                                                        }\n                                                    ],\n                                                    "comment": " 扩展字段：这里自定义 JSON 格式的 Key/Value 信息，以供业务使用。"\n                                                }\n                                            }\n                                        ],\n                                        "comment": " Android 平台上的通知，被 MTPush SDK 按照一定的通知栏样式展示。"\n                                    },\n                                    "ios": {\n                                        "notnull": true,\n                                        "type": "object",\n                                        "valueLevel": 0,\n                                        "values": [\n                                            {\n                                                "alert": {\n                                                    "notnull": true,\n                                                    "type": "string",\n                                                    "valueLevel": 3,\n                                                    "values": [],\n                                                    "lengthLevel": 1,\n                                                    "lengths": [\n                                                        11\n                                                    ],\n                                                    "repeat": 16,\n                                                    "comment": "String 或 JSON Object，通知内容：这里指定内容将会覆盖上级统一指定的 alert 信息。内容为空则不展示到通知栏。支持字符串形式也支持官方定义的 alert payload结构，在该结构中包含 title 和 subtitle 等官方支持的 key。"\n                                                },\n                                                "sound": {\n                                                    "notnull": false,\n                                                    "type": "string",\n                                                    "valueLevel": 3,\n                                                    "values": [],\n                                                    "lengthLevel": 1,\n                                                    "lengths": [\n                                                        7\n                                                    ],\n                                                    "repeat": 16,\n                                                    "comment": " String 或 JSON Object，通知提示声音：普通通知： String 类型。如果无此字段，则此消息无声音提示；有此字段，如果找到了指定的声音就播放该声音，否则播放默认声音。如果此字段为空字符串，iOS 7 为默认声音，iOS 8 及以上系统为无声音。告警通知： JSON Object , 支持官方定义的 payload 结构，在该结构中包含 critical 、name 和 volume 等官方支持的 key 。"\n                                                },\n                                                "badge": {\n                                                    "notnull": false,\n                                                    "type": "string",\n                                                    "valueLevel": 3,\n                                                    "values": [],\n                                                    "lengthLevel": 1,\n                                                    "lengths": [\n                                                        2\n                                                    ],\n                                                    "repeat": 16,\n                                                    "comment": " Int 或 String，应用角标：可设置为 N、+N、-N，N 的取值范围为 [0,99]。若上传的角标值 value 为 10，表示角标会设置为 N、10+N、10-N（值小于 0 时默认清除角标）。为 0 或空字符串，则表示清除角标。如果不填，表示不改变角标数字。MTPush 官方 API Library(SDK) 会默认填充badge值为\"+1\"。"\n                                                },\n                                                "extras": {\n                                                    "notnull": false,\n                                                    "type": "object",\n                                                    "valueLevel": 0,\n                                                    "values": [\n                                                        {\n                                                            "newsid": {\n                                                                "notnull": true,\n                                                                "type": "integer",\n                                                                "valueLevel": 0,\n                                                                "values": [\n                                                                    321\n                                                                ],\n                                                                "lengthLevel": 1,\n                                                                "lengths": [\n                                                                    3\n                                                                ],\n                                                                "repeat": 32,\n                                                                "trend": {\n                                                                    "top": 16\n                                                                }\n                                                            }\n                                                        }\n                                                    ],\n                                                    "comment": " 扩展字段：这里自定义 Key/value 信息，以供业务使用。"\n                                                }\n                                            }\n                                        ],\n                                        "comment": "iOS 平台上 APNs 通知。该通知内容会由 MTPush 代理发往 Apple APNs 服务器，并在 iOS 设备上在系统通知的方式呈现。"\n                                    },\n                                    "alert": {\n                                        "type": "string",\n                                        "notnull": false,\n                                        "comment": "String 或 JSON Object，通知内容：这里指定后会覆盖上级统一指定的 alert 信息。内容可以为空字符串，表示不展示到通知栏。各推送通道对此字段的限制详见 推送限制。"\n                                    },\n                                    "title": {\n                                        "type": "string",\n                                        "notnull": false,\n                                        "comment": " 通知标题：如果指定了，则通知里原来展示 App 名称的地方，将展示 title。各推送通道对此字段的限制详见 推送限制 。"\n                                    },\n                                    "builder_id": {\n                                        "type": "integer",\n                                        "notnull": false,\n                                        "comment": " 通知栏样式ID：Android SDK 可 设置通知栏样式，这里根据样式 ID 来指定该使用哪套样式。"\n                                    },\n                                    "extras": {\n                                        "type": "object",\n                                        "notnull": false,\n                                        "comment": " 扩展字段：这里自定义 JSON 格式的 Key/Value 信息，以供业务使用。"\n                                    }\n                                }\n                            ],\n                            "comment": "通知内容体，是被推送到客户端的内容。与 message 一起二者必须有其一，二者不可以并存。"\n                        },\n                        "message": {\n                            "notnull": true,\n                            "type": "object",\n                            "valueLevel": 0,\n                            "values": [\n                                {\n                                    "msg_content": {\n                                        "notnull": true,\n                                        "type": "string",\n                                        "valueLevel": 3,\n                                        "values": [],\n                                        "lengthLevel": 1,\n                                        "lengths": [\n                                            9\n                                        ],\n                                        "repeat": 16,\n                                        "comment": "String 或 JSON Object，消息内容本身"\n                                    },\n                                    "content_type": {\n                                        "notnull": false,\n                                        "type": "string",\n                                        "valueLevel": 3,\n                                        "values": [],\n                                        "lengthLevel": 1,\n                                        "lengths": [\n                                            4\n                                        ],\n                                        "repeat": 16,\n                                        "comment": " 消息内容类型"\n                                    },\n                                    "title": {\n                                        "notnull": false,\n                                        "type": "string",\n                                        "valueLevel": 3,\n                                        "values": [],\n                                        "lengthLevel": 1,\n                                        "lengths": [\n                                            3\n                                        ],\n                                        "repeat": 16,\n                                        "comment": " 消息标题"\n                                    },\n                                    "extras": {\n                                        "notnull": false,\n                                        "type": "object",\n                                        "valueLevel": 0,\n                                        "values": [\n                                            {\n                                                "key": {\n                                                    "notnull": true,\n                                                    "type": "string",\n                                                    "valueLevel": 3,\n                                                    "values": [],\n                                                    "lengthLevel": 1,\n                                                    "lengths": [\n                                                        5\n                                                    ],\n                                                    "repeat": 16\n                                                }\n                                            }\n                                        ],\n                                        "comment": " JSON 格式的可选参数"\n                                    }\n                                }\n                            ],\n                            "comment": "消息内容体，是被推送到客户端的内容。与 notification 一起二者必须有其一，二者不可以并存。"\n                        },\n                        "options": {\n                            "notnull": false,\n                            "type": "object",\n                            "valueLevel": 0,\n                            "values": [\n                                {\n                                    "time_to_live": {\n                                        "notnull": false,\n                                        "type": "integer",\n                                        "valueLevel": 0,\n                                        "values": [\n                                            60\n                                        ],\n                                        "lengthLevel": 1,\n                                        "lengths": [\n                                            2\n                                        ],\n                                        "repeat": 32,\n                                        "trend": {\n                                            "top": 16\n                                        },\n                                        "comment": " Int 或 String，离线消息保留时长(秒)：若推送时用户不在线，可为该用户保留指定时长的离线消息，以便其上线时再次推送。默认 86400 （1 天），最长 15 天，若厂商支持的最大值 < 传递的有效值，则以厂商最大值为准。设置为 0 表示不保留离线消息，只有推送当前在线的用户可以收到。"\n                                    },\n                                    "apns_production": {\n                                        "notnull": false,\n                                        "type": "boolean",\n                                        "valueLevel": 0,\n                                        "values": [\n                                            false\n                                        ],\n                                        "lengthLevel": 1,\n                                        "lengths": [],\n                                        "repeat": 16,\n                                        "comment": " APNs 是否生产环境：该字段仅对 iOS 的 Notification 有效，如果不指定则为推送生产环境。注意：MTPush 官方 API LIbrary (SDK) 默认设置为推送 “开发环境”。true：表示推送生产环境。false：表示推送开发环境。"\n                                    }\n                                }\n                            ],\n                            "comment": " 推送参数"\n                        },\n                        "ios": {\n                            "type": "object",\n                            "notnull": false,\n                            "comment": "ios 平台推送参数，详见 ios 说明"\n                        }\n                    }\n                ],\n                "comment": "发送请求体"\n            },\n            "request_id": {\n                "notnull": false,\n                "type": "string",\n                "valueLevel": 3,\n                "values": [],\n                "lengthLevel": 1,\n                "lengths": [\n                    8\n                ],\n                "repeat": 16,\n                "comment": " 客户自定义的可选字段，客户用来标识是哪条请求，响应时返回。"\n            },\n            "custom_args": {\n                "notnull": false,\n                "type": "string",\n                "valueLevel": 3,\n                "values": [],\n                "lengthLevel": 1,\n                "lengths": [\n                    13\n                ],\n                "repeat": 16,\n                "comment": " 客户自定义的可选字段，回调时返回给客户。"\n            },\n            "notification": {\n                "values": [\n                    {\n                        "type": "number",\n                        "notnull": false,\n                        "android": {\n                            "values": [\n                                {\n                                    "type": "number",\n                                    "notnull": false,\n                                    "large_icon": {\n                                        "type": "string",\n                                        "notnull": true,\n                                        "comment": "push.api.engagelab.cc/largeIcon.jpg\","\n                                    },\n                                    "small_icon": {\n                                        "type": "string",\n                                        "notnull": true,\n                                        "comment": "www.small.com/small_icon.jpg\","\n                                    }\n                                }\n                            ]\n                        }\n                    }\n                ]\n            },\n            "third_party_channel": {\n                "values": [\n                    {\n                        "type": "number",\n                        "notnull": false,\n                        "xiaomi": {\n                            "values": [\n                                {\n                                    "type": "number",\n                                    "notnull": false,\n                                    "small_icon_uri": {\n                                        "type": "string",\n                                        "notnull": true,\n                                        "comment": "f6.market.xiaomi.com/download/MiPass/x/x.png\","\n                                    }\n                                }\n                            ]\n                        },\n                        "huawei": {\n                            "values": [\n                                {\n                                    "type": "number",\n                                    "notnull": false,\n                                    "small_icon_uri": {\n                                        "type": "string",\n                                        "notnull": true,\n                                        "comment": "xx.com/xx.jpg\","\n                                    }\n                                }\n                            ]\n                        }\n                    }\n                ]\n            }\n        }\n    ]\n}', 'Authorization: Basic Yzk2ZjQyZTBkMmU2NjJlNDVkMDM1YWIxOmRmNGQ1OWU4NGVhYzJmOWQ1M2IzNmYxMg==', '2023-04-25 14:31:43');
INSERT INTO "Document" ("id", "userId", "testAccountId", "version", "name", "type", "url", "request", "standard", "header", "date") VALUES (1682434635082, 82002, 0, 3, '定时任务 API', 'JSON', '/v4/schedules', '{\n    "name": "定时推送示例",\n    "enabled": true,\n    "trigger": {\n        "single": {\n            "time": "2022-11-23 19:20:00",\n            "zone_type": 1\n        }\n    },\n    "push": {\n        "from": "push",\n        "to": "all",\n        "body": {\n            "platform": "all",\n            "notification": {\n                "android": {\n                    "alert": "Hi, Push!",\n                    "title": "Send to Android",\n                    "builder_id": 1,\n                    "extras": {\n                        "newsid": 321\n                    }\n                },\n                "ios": {\n                    "alert": "Hi, MTPush!",\n                    "sound": "default",\n                    "badge": "+1",\n                    "extras": {\n                        "newsid": 321\n                    }\n                }\n            },\n            "message": {\n                "msg_content": "Hi,MTPush",\n                "content_type": "text",\n                "title": "msg",\n                "extras": {\n                    "key": "value"\n                }\n            },\n            "options": {\n                "time_to_live": 60,\n                "apns_production": false\n            }\n        },\n        "request_id": "12345678",\n        "custom_args": "business info"\n    }\n}', '{\n    "notnull": true,\n    "type": "object",\n    "valueLevel": 0,\n    "values": [\n        {\n            "name": {\n                "notnull": true,\n                "type": "string",\n                "valueLevel": 3,\n                "values": [],\n                "lengthLevel": 1,\n                "lengths": [\n                    6\n                ],\n                "repeat": 4,\n                "comment": "表示 schedule 任务的名字，不得超过 255 字节，由汉字、字母、数字、下划线组成。"\n            },\n            "enabled": {\n                "notnull": true,\n                "type": "boolean",\n                "valueLevel": 0,\n                "values": [\n                    true\n                ],\n                "lengthLevel": 1,\n                "lengths": [],\n                "comment": "表示任务当前状态，创建任务时必须为 true。",\n                "repeat": 4\n            },\n            "trigger": {\n                "notnull": true,\n                "type": "object",\n                "valueLevel": 0,\n                "values": [\n                    {\n                        "single": {\n                            "notnull": true,\n                            "type": "object",\n                            "valueLevel": 0,\n                            "values": [\n                                {\n                                    "time": {\n                                        "notnull": true,\n                                        "type": "string",\n                                        "valueLevel": 3,\n                                        "values": [],\n                                        "lengthLevel": 1,\n                                        "lengths": [\n                                            19\n                                        ],\n                                        "repeat": 4,\n                                        "comment": "表示定时任务的触发时间，使用 yyyy-mm-dd hh:mm:ss的标准时间格式表示。如 \"2014-02-15 13:16:59\"，不能为 \"2014-2-15 13:16:59\" 或 \"2014-12-15 13:16\"，即日期时间格式必须完整。定时任务的最晚时间不能超过一年。"\n                                    },\n                                    "zone_type": {\n                                        "notnull": true,\n                                        "type": "integer",\n                                        "valueLevel": 0,\n                                        "values": [\n                                            1\n                                        ],\n             