INSERT INTO "Document" ("id", "userId", "testAccountId", "version", "name", "type", "url", "request", "standard", "header", "date") VALUES (1755827879185, 1635169494440, 0, 3, '新 APIAuto 只要对象为空 {} 则整个 Request JSON 都不显示绿色注释，像是报错了', 'JSON', '/get', '{\n    "[]": {\n        "Moment": {},\n        "User": {\n            "id@": "/Moment/userId"\n        }\n    }\n}', '{\n    "notNull": true,\n    "notEmpty": true,\n    "type": "object",\n    "valueLevel": 0,\n    "values": [\n        {\n            "[]": {\n                "notNull": true,\n                "notEmpty": true,\n                "type": "object",\n                "valueLevel": 0,\n                "values": [\n                    {\n                        "Moment": {\n                            "notNull": true,\n                            "notEmpty": false,\n                            "type": "object",\n                            "valueLevel": 0,\n                            "values": [\n                                {}\n                            ]\n                        },\n                        "User": {\n                            "notNull": true,\n                            "notEmpty": true,\n                            "type": "object",\n                            "valueLevel": 0,\n                            "values": [\n                                {\n                                    "id@": {\n                                        "notNull": true,\n                                        "notEmpty": true,\n                                        "type": "string",\n                                        "valueLevel": 3,\n                                        "format": "",\n                                        "values": [],\n                                        "lengthLevel": 1,\n                                        "lengths": [\n                                            14\n                                        ]\n                                    }\n                                }\n                            ]\n                        }\n                    }\n                ]\n            }\n        }\n    ]\n}', '', '2026-01-25 16:48:48');
